<?php
require 'config.php';
$count=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && $count===0){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12){$error='Enter a name, valid email and password with at least 12 characters.';}else{$q=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'admin')");$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);echo 'Admin created. <a href="login.php">Login now</a>. Delete setup.php after use.';exit;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Initial store setup</title><link rel="stylesheet" href="assets/css/store-theme.css"></head><body class="auth-page"><main class="auth-card"><h1>First-time admin setup</h1><?php if($count>0):?><p>An admin account already exists. Setup is locked. Delete setup.php.</p><?php else:?><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Admin name</label><input name="name" required><label>Admin email</label><input name="email" type="email" required><label>Strong password (12+ characters)</label><input name="password" type="password" minlength="12" required><button class="primary-btn full">Create admin account</button></form><?php endif;?></main></body></html>